from pathlib import Path
C=Path('work/deliverables/undertow/elements')
def add(n,s):p=C/n/'element.css';p.write_text(p.read_text()+'\n'+s)
add('concentric','.orbit[data-el="undertow-concentric"] .ring:nth-child(3):not(.on) {background:var(--n-8);color:var(--page);}')
add('chart-scatter','.scatter[data-el="undertow-chart-scatter"] .dot.on span {background:var(--a1);color:var(--a1-on);padding:calc(var(--gap-sm)/3) calc(var(--gap-sm)/2);border-radius:999px;}')
add('chart-area','.areas[data-el="undertow-chart-area"] {overflow:hidden;} .areas[data-el="undertow-chart-area"] .series {overflow:visible;}')
p=C/'chart-line/element.css';s=p.read_text();s=s.replace('top:anchor(var(--undertow-prev) bottom); bottom:anchor(var(--undertow-self) bottom);','top:calc(anchor(var(--undertow-prev) bottom) - 1px); bottom:calc(anchor(var(--undertow-self) bottom) - 1px);').replace('top:anchor(var(--undertow-self) bottom); bottom:anchor(var(--undertow-prev) bottom);','top:calc(anchor(var(--undertow-self) bottom) - 1px); bottom:calc(anchor(var(--undertow-prev) bottom) - 1px);');p.write_text(s)
r='.cycle[data-el="undertow-cycle"]';s=r+' {display:block;isolation:isolate;} '+r+' .core {position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(22%,190px);} '+r+' .node {position:absolute;left:calc(50% + 37%*sin(var(--undertow-cycle-angle)));top:calc(50% - 37%*cos(var(--undertow-cycle-angle)));width:22%;height:20%;transform:translate(-50%,-50%);grid-area:auto;--undertow-cycle-dx:calc(37cqw*(sin(var(--undertow-cycle-angle) + 360deg/var(--undertow-cycle-count)) - sin(var(--undertow-cycle-angle))));--undertow-cycle-dy:calc(37cqh*(cos(var(--undertow-cycle-angle)) - cos(var(--undertow-cycle-angle) + 360deg/var(--undertow-cycle-count))));} '+r+' .node::after {left:50%;top:50%;width:hypot(var(--undertow-cycle-dx),var(--undertow-cycle-dy));height:1px;border:0;background:var(--n-4);transform:rotate(atan2(var(--undertow-cycle-dy),var(--undertow-cycle-dx)));transform-origin:left;z-index:-1;} '+r+' .node::before {content:"";position:absolute;left:calc(50% + var(--undertow-cycle-dx)/2);top:calc(50% + var(--undertow-cycle-dy)/2);width:9px;height:9px;clip-path:polygon(0 0,100% 50%,0 100%);background:var(--n-5);transform:translate(-50%,-50%) rotate(atan2(var(--undertow-cycle-dy),var(--undertow-cycle-dx)));z-index:-1;}'
for n in range(3,7):s+=r+f':has(> .node:nth-child({n} of .node):last-child) {{ --undertow-cycle-count:{n};}}'
for i in range(1,7):s+=r+f' .node:nth-child({i} of .node) {{ --undertow-cycle-angle:calc({i-1}*360deg/var(--undertow-cycle-count));}}'
add('cycle',s)
for n,root in [('flowchart','flowchart'),('swimlane','swimlane')]:
 r='.'+root+'[data-el="undertow-'+n+'"]';add(n,r+' .node.to-r::after {border:0;height:8px;top:calc(50% - 4px);background:var(--n-5);clip-path:polygon(0 40%,80% 40%,80% 0,100% 50%,80% 100%,80% 60%,0 60%);} '+r+' .node.to-l::after {border:0;height:8px;top:calc(50% - 4px);background:var(--n-5);clip-path:polygon(100% 40%,20% 40%,20% 0,0 50%,20% 100%,20% 60%,100% 60%);} '+r+' .node.to-d::before {border:0;width:8px;left:calc(50% - 4px);background:var(--n-5);clip-path:polygon(40% 0,60% 0,60% 80%,100% 80%,50% 100%,0 80%,40% 80%);} '+r+' .node.to-u::before {border:0;width:8px;left:calc(50% - 4px);background:var(--n-5);clip-path:polygon(40% 100%,60% 100%,60% 20%,100% 20%,50% 0,0 20%,40% 20%);}')
p=C/'radar/element.css';s=p.read_text().replace('clip-path:polygon(','--undertow-radar-clip:polygon(');r='.radar[data-el="undertow-radar"]';s+='\n'+r+' .series {background:none;opacity:1;clip-path:none;} '+r+' .series::before {content:"";position:absolute;inset:0;background:var(--a1-3-soft);opacity:.75;clip-path:var(--undertow-radar-clip);} '+r+' .series:nth-last-child(1) {background:none;opacity:1;} '+r+' .series:nth-last-child(1)::before {background:var(--n-4);opacity:.45;} '+r+' .series .name {display:block;position:absolute;top:calc(var(--gap-lg)*-1);left:0;font-size:var(--type-14);white-space:nowrap;} '+r+' .series:nth-last-child(1) .name {left:50%;} @container (max-width:600px) {'+r+' .series .name {font-size:var(--type-12);}}';p.write_text(s)
